CREATE TABLE collectors (collector_id TEXT PRIMARY KEY, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), fixture_mode INTEGER NOT NULL DEFAULT 1 CHECK(fixture_mode IN (0,1)), created_at INTEGER NOT NULL, last_seen_at INTEGER, last_quota_capture_at INTEGER, last_source_event_at INTEGER);
CREATE TABLE collector_keys (key_id TEXT PRIMARY KEY, collector_id TEXT NOT NULL REFERENCES collectors(collector_id), active_from INTEGER NOT NULL, valid_until INTEGER, revoked_at INTEGER);
CREATE INDEX collector_keys_collector_idx ON collector_keys(collector_id);
ALTER TABLE provider_config ADD COLUMN authoritative_collector_id TEXT REFERENCES collectors(collector_id);
ALTER TABLE provider_config ADD COLUMN complete_set_verified INTEGER NOT NULL DEFAULT 0 CHECK(complete_set_verified IN (0,1));
ALTER TABLE provider_config ADD COLUMN latest_sequence INTEGER NOT NULL DEFAULT 0;
ALTER TABLE provider_config ADD COLUMN last_collected_at INTEGER;
ALTER TABLE provider_config ADD COLUMN data_status TEXT NOT NULL DEFAULT 'unavailable';
ALTER TABLE provider_config ADD COLUMN error_code TEXT;
CREATE TABLE quota_observations (observation_id TEXT PRIMARY KEY, collector_id TEXT NOT NULL REFERENCES collectors(collector_id), provider_id TEXT NOT NULL REFERENCES provider_config(provider_id), event_id TEXT NOT NULL, generation INTEGER NOT NULL, sequence INTEGER NOT NULL CHECK(sequence>0), collected_at INTEGER NOT NULL, upstream_observed_at INTEGER, received_at INTEGER NOT NULL, payload TEXT NOT NULL, UNIQUE(collector_id,event_id), UNIQUE(collector_id,provider_id,generation,sequence));
CREATE INDEX quota_observations_order_idx ON quota_observations(provider_id,generation,sequence);
CREATE INDEX quota_observations_source_idx ON quota_observations(provider_id,upstream_observed_at);
CREATE TABLE quota_windows (observation_id TEXT NOT NULL REFERENCES quota_observations(observation_id), window_id TEXT NOT NULL, used_percent REAL CHECK(used_percent IS NULL OR used_percent BETWEEN 0 AND 100), remaining_percent REAL CHECK(remaining_percent IS NULL OR remaining_percent BETWEEN 0 AND 100), duration_seconds INTEGER CHECK(duration_seconds IS NULL OR duration_seconds>0), reset_at INTEGER, payload TEXT NOT NULL, PRIMARY KEY(observation_id,window_id));
CREATE INDEX quota_windows_reset_idx ON quota_windows(reset_at);
CREATE TABLE current_windows (provider_id TEXT NOT NULL REFERENCES provider_config(provider_id), window_id TEXT NOT NULL, observation_id TEXT NOT NULL REFERENCES quota_observations(observation_id), payload TEXT NOT NULL, data_status TEXT NOT NULL, PRIMARY KEY(provider_id,window_id));
CREATE TABLE ingestion_receipts (collector_id TEXT NOT NULL REFERENCES collectors(collector_id), event_id TEXT NOT NULL, body_hash TEXT NOT NULL, provider_id TEXT NOT NULL REFERENCES provider_config(provider_id), generation INTEGER NOT NULL, sequence INTEGER NOT NULL, observation_id TEXT REFERENCES quota_observations(observation_id), outcome TEXT NOT NULL CHECK(outcome IN ('accepted','superseded')), received_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(collector_id,event_id));
CREATE INDEX ingestion_receipts_expiry_idx ON ingestion_receipts(expires_at);
CREATE TABLE ingestion_nonces (key_id TEXT NOT NULL REFERENCES collector_keys(key_id), nonce TEXT NOT NULL, accepted_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(key_id,nonce));
CREATE INDEX ingestion_nonces_expiry_idx ON ingestion_nonces(expires_at);
CREATE TABLE operational_state (resource TEXT PRIMARY KEY, updated_at INTEGER NOT NULL, last_code TEXT);
